		/** 取词 + {name} 插值；缺键回退 en，再缺回显 key（fail loud，对齐官方 lookup 链）。 */
		function tr(lang, key, vars) {
			let s = DICTS[lang][key] ?? DICTS.en[key] ?? key;
			if (vars) for (const [k, v] of Object.entries(vars)) s = s.split("{" + k + "}").join(String(v));
			return s;
		}
